// Board state, make/unmake, attack detection and move generation.
// Replaces cachCore's Board, BoardSquare, Position, Piece classes, Movement and the rules helpers.
// Squares: a1 = 0, h1 = 7, a8 = 56, h8 = 63. Moves are generated by scanning squares in a fixed
// order and there are no piece lists, so a position always produces the same moves (ledger E3).

export const WHITE = 0;
export const BLACK = 1;
export type Side = 0 | 1;

export const KING = 1;
export const QUEEN = 2;
export const ROOK = 3;
export const BISHOP = 4;
export const KNIGHT = 5;
export const PAWN = 6;

export const WK = 1;
export const WQ = 2;
export const BK = 4;
export const BQ = 8;

export const FLAG_CAPTURE = 1;
export const FLAG_EN_PASSANT = 2;
export const FLAG_CASTLE = 4;
export const FLAG_DOUBLE = 8;

export const makePiece = (type: number, side: Side): number => type | (side << 3);
export const typeOf = (piece: number): number => piece & 7;
export const sideOf = (piece: number): Side => (piece >> 3) as Side;
export const other = (side: Side): Side => (side ^ 1) as Side;

export const encodeMove = (from: number, to: number, promo = 0, flags = 0): number =>
  from | (to << 6) | (promo << 12) | (flags << 15);
export const moveFrom = (m: number): number => m & 63;
export const moveTo = (m: number): number => (m >> 6) & 63;
export const movePromo = (m: number): number => (m >> 12) & 7;
export const moveFlags = (m: number): number => (m >> 15) & 15;
export const isCapture = (m: number): boolean => (moveFlags(m) & FLAG_CAPTURE) !== 0;
export const isCastle = (m: number): boolean => (moveFlags(m) & FLAG_CASTLE) !== 0;

export const fileOf = (sq: number): number => sq & 7;
export const rankOf = (sq: number): number => sq >> 3;
export const sqName = (sq: number): string => String.fromCharCode(97 + fileOf(sq)) + (rankOf(sq) + 1);
export const sqFromName = (name: string): number => {
  const f = name.charCodeAt(0) - 97;
  const r = name.charCodeAt(1) - 49;
  return name.length === 2 && f >= 0 && f < 8 && r >= 0 && r < 8 ? r * 8 + f : -1;
};

const ORTHO = [[-1, 0], [1, 0], [0, 1], [0, -1]]; // left, right, up, down
const DIAG = [[-1, 1], [1, 1], [-1, -1], [1, -1]]; // left-up, right-up, left-down, right-down
const KNIGHT_STEPS = [[-1, -2], [-2, -1], [-1, 2], [-2, 1], [1, -2], [2, -1], [1, 2], [2, 1]];

function buildRays(dirs: number[][]): number[][][] {
  const table: number[][][] = [];
  for (let sq = 0; sq < 64; sq++) {
    table.push(dirs.map(([df, dr]) => {
      const ray: number[] = [];
      let f = fileOf(sq) + df;
      let r = rankOf(sq) + dr;
      while (f >= 0 && f < 8 && r >= 0 && r < 8) {
        ray.push(r * 8 + f);
        f += df;
        r += dr;
      }
      return ray;
    }));
  }
  return table;
}

function buildSteps(steps: number[][]): number[][] {
  const table: number[][] = [];
  for (let sq = 0; sq < 64; sq++) {
    const out: number[] = [];
    for (const [df, dr] of steps) {
      const f = fileOf(sq) + df;
      const r = rankOf(sq) + dr;
      if (f >= 0 && f < 8 && r >= 0 && r < 8) out.push(r * 8 + f);
    }
    table.push(out);
  }
  return table;
}

const ORTHO_RAYS = buildRays(ORTHO);
const DIAG_RAYS = buildRays(DIAG);
const KNIGHT_TARGETS = buildSteps(KNIGHT_STEPS);
const KING_TARGETS = buildSteps([...ORTHO, ...DIAG]);

const CASTLE_MASK = new Uint8Array(64).fill(15);
CASTLE_MASK[0] = 15 & ~WQ;
CASTLE_MASK[4] = 15 & ~(WK | WQ);
CASTLE_MASK[7] = 15 & ~WK;
CASTLE_MASK[56] = 15 & ~BQ;
CASTLE_MASK[60] = 15 & ~(BK | BQ);
CASTLE_MASK[63] = 15 & ~BK;

const PROMOTIONS = [QUEEN, ROOK, BISHOP, KNIGHT];

export class Position {
  board = new Int8Array(64);
  side: Side = WHITE;
  castling = 0;
  ep = -1;
  halfmove = 0;
  fullmove = 1;
  kingSq: [number, number] = [-1, -1];
  private undoStack: number[] = [];

  clone(): Position {
    const p = new Position();
    p.board.set(this.board);
    p.side = this.side;
    p.castling = this.castling;
    p.ep = this.ep;
    p.halfmove = this.halfmove;
    p.fullmove = this.fullmove;
    p.kingSq = [this.kingSq[0], this.kingSq[1]];
    return p;
  }

  isAttacked(sq: number, by: Side): boolean {
    const b = this.board;
    const f = fileOf(sq);
    const pawn = makePiece(PAWN, by);
    if (by === WHITE) {
      if (f > 0 && sq >= 9 && b[sq - 9] === pawn) return true;
      if (f < 7 && sq >= 7 && b[sq - 7] === pawn) return true;
    } else {
      if (f > 0 && sq + 7 < 64 && b[sq + 7] === pawn) return true;
      if (f < 7 && sq + 9 < 64 && b[sq + 9] === pawn) return true;
    }
    const knight = makePiece(KNIGHT, by);
    for (const t of KNIGHT_TARGETS[sq]) if (b[t] === knight) return true;
    const king = makePiece(KING, by);
    for (const t of KING_TARGETS[sq]) if (b[t] === king) return true;

    const queen = makePiece(QUEEN, by);
    const rook = makePiece(ROOK, by);
    for (const ray of ORTHO_RAYS[sq]) {
      for (const t of ray) {
        const p = b[t];
        if (p !== 0) {
          if (p === rook || p === queen) return true;
          break;
        }
      }
    }
    const bishop = makePiece(BISHOP, by);
    for (const ray of DIAG_RAYS[sq]) {
      for (const t of ray) {
        const p = b[t];
        if (p !== 0) {
          if (p === bishop || p === queen) return true;
          break;
        }
      }
    }
    return false;
  }

  inCheck(side: Side): boolean {
    return this.isAttacked(this.kingSq[side], other(side));
  }

  /** Pseudo-legal moves for the side to move. Castling moves are fully validated here. */
  generatePseudo(): number[] {
    const moves: number[] = [];
    const b = this.board;
    const us = this.side;
    for (let sq = 0; sq < 64; sq++) {
      const piece = b[sq];
      if (piece === 0 || sideOf(piece) !== us) continue;
      switch (typeOf(piece)) {
        case PAWN:
          this.pawnMoves(sq, us, moves);
          break;
        case KNIGHT:
          this.stepMoves(sq, KNIGHT_TARGETS[sq], us, moves);
          break;
        case KING:
          this.stepMoves(sq, KING_TARGETS[sq], us, moves);
          break;
        case BISHOP:
          this.rayMoves(sq, DIAG_RAYS[sq], us, moves);
          break;
        case ROOK:
          this.rayMoves(sq, ORTHO_RAYS[sq], us, moves);
          break;
        case QUEEN:
          this.rayMoves(sq, ORTHO_RAYS[sq], us, moves);
          this.rayMoves(sq, DIAG_RAYS[sq], us, moves);
          break;
      }
    }
    this.castleMoves(us, moves);
    return moves;
  }

  private stepMoves(from: number, targets: number[], us: Side, out: number[]): void {
    const b = this.board;
    for (const t of targets) {
      const p = b[t];
      if (p === 0) out.push(encodeMove(from, t));
      else if (sideOf(p) !== us) out.push(encodeMove(from, t, 0, FLAG_CAPTURE));
    }
  }

  private rayMoves(from: number, rays: number[][], us: Side, out: number[]): void {
    const b = this.board;
    for (const ray of rays) {
      for (const t of ray) {
        const p = b[t];
        if (p === 0) {
          out.push(encodeMove(from, t));
        } else {
          if (sideOf(p) !== us) out.push(encodeMove(from, t, 0, FLAG_CAPTURE));
          break;
        }
      }
    }
  }

  private pawnMoves(from: number, us: Side, out: number[]): void {
    const b = this.board;
    const dir = us === WHITE ? 8 : -8;
    const startRank = us === WHITE ? 1 : 6;
    const lastRank = us === WHITE ? 7 : 0;
    const one = from + dir;
    const add = (to: number, flags: number): void => {
      if (rankOf(to) === lastRank) {
        for (const promo of PROMOTIONS) out.push(encodeMove(from, to, promo, flags));
      } else {
        out.push(encodeMove(from, to, 0, flags));
      }
    };
    if (b[one] === 0) {
      add(one, 0);
      if (rankOf(from) === startRank && b[one + dir] === 0) {
        out.push(encodeMove(from, one + dir, 0, FLAG_DOUBLE));
      }
    }
    const file = fileOf(from);
    for (const df of [-1, 1]) {
      if (file + df < 0 || file + df > 7) continue;
      const to = one + df;
      const p = b[to];
      if (p !== 0) {
        if (sideOf(p) !== us) add(to, FLAG_CAPTURE);
      } else if (to === this.ep) {
        out.push(encodeMove(from, to, 0, FLAG_CAPTURE | FLAG_EN_PASSANT));
      }
    }
  }

  private castleMoves(us: Side, out: number[]): void {
    const rights = us === WHITE ? this.castling & (WK | WQ) : this.castling & (BK | BQ);
    if (rights === 0) return;
    const king = us === WHITE ? 4 : 60;
    const them = other(us);
    const b = this.board;
    if (this.isAttacked(king, them)) return;
    if (rights & (WK | BK) && b[king + 1] === 0 && b[king + 2] === 0
      && !this.isAttacked(king + 1, them) && !this.isAttacked(king + 2, them)) {
      out.push(encodeMove(king, king + 2, 0, FLAG_CASTLE));
    }
    if (rights & (WQ | BQ) && b[king - 1] === 0 && b[king - 2] === 0 && b[king - 3] === 0
      && !this.isAttacked(king - 1, them) && !this.isAttacked(king - 2, them)) {
      out.push(encodeMove(king, king - 2, 0, FLAG_CASTLE));
    }
  }

  /** Applies a pseudo-legal move for the side to move. */
  make(m: number): void {
    const b = this.board;
    const from = moveFrom(m);
    const to = moveTo(m);
    const flags = moveFlags(m);
    const promo = movePromo(m);
    const piece = b[from];
    const us = this.side;
    const captured = flags & FLAG_EN_PASSANT ? makePiece(PAWN, other(us)) : b[to];

    this.undoStack.push(captured | (this.castling << 4) | ((this.ep + 1) << 8) | (this.halfmove << 15));

    b[from] = 0;
    b[to] = promo ? makePiece(promo, us) : piece;
    if (flags & FLAG_EN_PASSANT) b[to + (us === WHITE ? -8 : 8)] = 0;
    if (flags & FLAG_CASTLE) {
      if (to > from) {
        b[to - 1] = b[to + 1];
        b[to + 1] = 0;
      } else {
        b[to + 1] = b[to - 2];
        b[to - 2] = 0;
      }
    }
    if (typeOf(piece) === KING) this.kingSq[us] = to;

    this.castling &= CASTLE_MASK[from] & CASTLE_MASK[to];
    this.ep = flags & FLAG_DOUBLE ? (from + to) >> 1 : -1;
    this.halfmove = typeOf(piece) === PAWN || captured !== 0 ? 0 : this.halfmove + 1;
    if (us === BLACK) this.fullmove++;
    this.side = other(us);
  }

  unmake(m: number): void {
    const b = this.board;
    const from = moveFrom(m);
    const to = moveTo(m);
    const flags = moveFlags(m);
    const packed = this.undoStack.pop() as number;
    const captured = packed & 15;
    const us = other(this.side);

    this.side = us;
    if (us === BLACK) this.fullmove--;
    this.castling = (packed >> 4) & 15;
    this.ep = ((packed >> 8) & 127) - 1;
    this.halfmove = packed >>> 15;

    const moved = movePromo(m) ? makePiece(PAWN, us) : b[to];
    b[from] = moved;
    if (flags & FLAG_EN_PASSANT) {
      b[to] = 0;
      b[to + (us === WHITE ? -8 : 8)] = captured;
    } else {
      b[to] = captured;
    }
    if (flags & FLAG_CASTLE) {
      if (to > from) {
        b[to + 1] = b[to - 1];
        b[to - 1] = 0;
      } else {
        b[to - 2] = b[to + 1];
        b[to + 1] = 0;
      }
    }
    if (typeOf(moved) === KING) this.kingSq[us] = from;
  }

  isLegal(m: number): boolean {
    const us = this.side;
    this.make(m);
    const legal = !this.isAttacked(this.kingSq[us], other(us));
    this.unmake(m);
    return legal;
  }

  generateLegal(): number[] {
    return this.generatePseudo().filter((m) => this.isLegal(m));
  }

  hasLegalMove(): boolean {
    for (const m of this.generatePseudo()) if (this.isLegal(m)) return true;
    return false;
  }

  /**
   * Identifies a position for threefold repetition: pieces, side to move, castling rights, and
   * the en passant square only when a legal en passant capture actually exists.
   */
  repetitionKey(): string {
    let ep = -1;
    if (this.ep >= 0) {
      for (const m of this.generatePseudo()) {
        if (moveFlags(m) & FLAG_EN_PASSANT && this.isLegal(m)) {
          ep = this.ep;
          break;
        }
      }
    }
    return String.fromCharCode(...this.board, this.side, this.castling, ep + 1);
  }

  /** K v K, K+N v K, or kings plus any number of bishops all on one square colour. */
  isInsufficientMaterial(): boolean {
    const b = this.board;
    let knights = 0;
    let bishops = 0;
    let bishopShades = 0;
    for (let sq = 0; sq < 64; sq++) {
      const p = b[sq];
      if (p === 0) continue;
      const t = typeOf(p);
      if (t === PAWN || t === ROOK || t === QUEEN) return false;
      if (t === KNIGHT) knights++;
      else if (t === BISHOP) {
        bishops++;
        bishopShades |= 1 << ((fileOf(sq) + rankOf(sq)) & 1);
      }
    }
    if (bishops === 0) return knights <= 1;
    return knights === 0 && bishopShades !== 3;
  }
}
